#pragma once
#include "features/streaming/domain/control_discovery.hpp"
#include <cstdio>
#include <string>
namespace stream::telemetry::network {
inline std::string discoveryShapeText(const DiscoveryShape& shape,bool* formattedTruncated=nullptr){std::string out;for(unsigned i=0;i<shape.count&&i<shape.tokens.size();++i){const auto& t=shape.tokens[i];using K=DiscoveryTokenKind;switch(t.kind){
case K::ObjectBegin:out+='{';break;case K::ObjectEnd:out+='}';break;case K::ArrayBegin:out+='[';break;case K::ArrayEnd:out+=']';break;case K::Comma:out+=',';break;case K::Ellipsis:out+="...";break;case K::Key:out+=t.code<DiscoveryKeys.size()?DiscoveryKeys[t.code]:DiscoveryKeys[0];out+=':';break;case K::Redacted:out+="<redacted>";break;
case K::Null:out+="null";break;case K::Bool:out+="bool";break;case K::Integer:out+="integer";break;case K::Number:out+="number";break;case K::String:out+="string";break;case K::Binary:out+="binary";break;case K::Invalid:out+="invalid";break;case K::ObjectDepth:out+="object{...}";break;case K::ArrayDepth:out+="array[...]";break;
case K::BooleanValue:out+=t.integer?"true":"false";break;case K::SignedValue:case K::UnsignedValue:out+=std::to_string(t.integer);break;case K::FloatValue:{char value[32];std::snprintf(value,sizeof(value),"%.4g",t.number);out+=value;break;}case K::FecMaskValue:{static constexpr const char* names[]={"random","bursty","kFecMaskRandom","kFecMaskBursty"};out+=t.code<4?names[t.code]:"string";break;}}
}if(shape.truncated)out+="...";if(out.size()>640){if(formattedTruncated)*formattedTruncated=true;out=out.substr(0,637)+"...";}return out;}
inline std::string discoveryClassificationText(const ControlDiscoveryDescription& d){static constexpr const char* kinds[]={"ignored","stats","ping","rumble","invalid-rumble","close","error","invalid"};return d.classification<8?std::string(" parsed=")+kinds[d.classification]:"";}
inline std::string discoverySchemaText(const ControlDiscoveryDescription& d){return std::string("id=")+(d.id<DiscoveryIds.size()?DiscoveryIds[d.id]:"unknown")+" schema="+discoveryShapeText(d.schema)+discoveryClassificationText(d);}
inline std::string discoverySampleText(const ControlDiscoveryDescription& d){if(d.binary||d.oversized)return std::string("event=")+(d.binary?"<binary>":"<oversized>")+" bytes="+std::to_string(d.bytes)+discoveryClassificationText(d);return std::string("id=")+(d.id<DiscoveryIds.size()?DiscoveryIds[d.id]:"unknown")+" bytes="+std::to_string(d.bytes)+" fields="+discoveryShapeText(d.sample)+discoveryClassificationText(d);}
inline std::string controlDiscoveryText(const ControlDiscoveryEvent& e){bool formatTruncated=false;discoveryShapeText(e.description.sample,&formatTruncated);std::string out;if(e.overflow)out="mtsControl schemaOverflow="+std::to_string(e.count)+" pending="+std::to_string(e.pending)+" schemas="+std::to_string(e.schemas);else out="mtsControl "+discoverySampleText(e.description)+" count="+std::to_string(e.count)+" pending="+std::to_string(e.pending)+" firstMs="+std::to_string(e.firstMs)+" lastMs="+std::to_string(e.lastMs);
 return out+" discoverySchema=2 unknownNames="+std::to_string(e.description.unknownNames)+" tokensTruncated="+std::to_string(e.description.sample.truncated||e.description.schema.truncated)+" formatterTruncated="+std::to_string(formatTruncated)+" discoverySequence="+std::to_string(e.sequence)+" discoveryDiscarded="+std::to_string(e.discarded);}
}
